   283	    DataTree(DigestCalculator digestCalculator) {
   284	        this.digestCalculator = digestCalculator;
   285	        nodes = new NodeHashMapImpl(digestCalculator);
   286	
   287	        // rather than fight it, let root have an alias
   288	        nodes.put("", root);
   289	        nodes.putWithoutDigest(rootZookeeper, root);
   290	
   291	        // add the proc node and quota node
   292	        root.addChild(procChildZookeeper);
   293	        nodes.put(procZookeeper, procDataNode);
   294	
   295	        procDataNode.addChild(quotaChildZookeeper);
   296	        nodes.put(quotaZookeeper, quotaDataNode);
   297	
   298	        addConfigNode();
   299	
   300	        nodeDataSize.set(approximateDataSize());
   301	        try {
   302	            dataWatches = WatchManagerFactory.createWatchManager();
   303	            childWatches = WatchManagerFactory.createWatchManager();
   304	        } catch (Exception e) {
   305	            LOG.error("Unexpected exception when creating WatchManager, exiting abnormally", e);
   306	            ServiceUtils.requestSystemExit(ExitCode.UNEXPECTED_ERROR.getValue());
   307	        }
   308	    }
