   399	    /**
   400	     * Add a new node to the DataTree.
   401	     * @param path
   402	     *            Path for the new node.
   403	     * @param data
   404	     *            Data to store in the node.
   405	     * @param acl
   406	     *            Node acls
   407	     * @param ephemeralOwner
   408	     *            the session id that owns this node. -1 indicates this is not
   409	     *            an ephemeral node.
   410	     * @param zxid
   411	     *            Transaction ID
   412	     * @param time
   413	     * @throws NodeExistsException
   414	     * @throws NoNodeException
   415	     */
   416	    public void createNode(final String path, byte[] data, List<ACL> acl, long ephemeralOwner, int parentCVersion, long zxid, long time) throws NoNodeException, NodeExistsException {
   417	        createNode(path, data, acl, ephemeralOwner, parentCVersion, zxid, time, null);
