   529	    /**
   530	     * remove the path from the datatree
   531	     *
   532	     * @param path
   533	     *            the path to of the node to be deleted
   534	     * @param zxid
   535	     *            the current zxid
   536	     * @throws NoNodeException
   537	     */
   538	    public void deleteNode(String path, long zxid) throws NoNodeException {
   539	        int lastSlash = path.lastIndexOf('/');
   540	        String parentName = path.substring(0, lastSlash);
   541	        String childName = path.substring(lastSlash + 1);
   542	
   543	        // The child might already be deleted during taking fuzzy snapshot,
   544	        // but we still need to update the pzxid here before throw exception
   545	        // for no such child
   546	        DataNode parent = nodes.get(parentName);
   547	        if (parent == null) {
   548	            throw new NoNodeException();
   549	        }
   550	        synchronized (parent) {
   551	            nodes.preChange(parentName, parent);
   552	            parent.removeChild(childName);
   553	            // Only update pzxid when the zxid is larger than the current pzxid,
   554	            // otherwise we might override some higher pzxid set by a CreateTxn,
   555	            // which could cause the cversion and pzxid inconsistent
   556	            if (zxid > parent.stat.getPzxid()) {
   557	                parent.stat.setPzxid(zxid);
   558	            }
   559	            nodes.postChange(parentName, parent);
   560	        }
   561	
   562	        DataNode node = nodes.get(path);
   563	        if (node == null) {
   564	            throw new NoNodeException();
   565	        }
   566	        List<ACL> acl;
   567	        nodes.remove(path);
   568	        synchronized (node) {
   569	            acl = getACL(node);
   570	            aclCache.removeUsage(node.acl);
   571	            nodeDataSize.addAndGet(-getNodeSize(path, node.data));
   572	        }
   573	
   574	        // Synchronized to sync the containers and ttls change, probably
   575	        // only need to sync on containers and ttls, will update it in a
   576	        // separate patch.
   577	        List<ACL> parentAcl;
   578	        synchronized (parent) {
   579	            parentAcl = getACL(parent);
   580	            long owner = node.stat.getEphemeralOwner();
   581	            EphemeralType ephemeralType = EphemeralType.get(owner);
   582	            if (ephemeralType == EphemeralType.CONTAINER) {
   583	                containers.remove(path);
   584	            } else if (ephemeralType == EphemeralType.TTL) {
   585	                ttls.remove(path);
   586	            } else if (owner != 0) {
   587	                Set<String> nodes = ephemerals.get(owner);
   588	                if (nodes != null) {
   589	                    synchronized (nodes) {
   590	                        nodes.remove(path);
   591	                    }
   592	                }
   593	            }
   594	        }
   595	
   596	        if (parentName.startsWith(procZookeeper) && Quotas.limitNode.equals(childName)) {
   597	            // delete the node in the trie.
   598	            // we need to update the trie as well
   599	            pTrie.deletePath(Quotas.trimQuotaPath(parentName));
   600	        }
   601	
   602	        // also check to update the quotas for this node
   603	        String lastPrefix = getMaxPrefixWithQuota(path);
   604	        if (lastPrefix != null) {
   605	            // ok we have some match and need to update
   606	            long bytes;
   607	            synchronized (node) {
   608	                bytes = (node.data == null ? 0 : -(node.data.length));
   609	            }
   610	            updateQuotaStat(lastPrefix, bytes, -1);
   611	        }
   612	
   613	        updateWriteStat(path, 0L);
   614	
   615	        if (LOG.isTraceEnabled()) {
   616	            ZooTrace.logTraceMessage(
   617	                LOG,
   618	                ZooTrace.EVENT_DELIVERY_TRACE_MASK,
   619	                "dataWatches.triggerWatch " + path);
   620	            ZooTrace.logTraceMessage(
   621	                LOG,
   622	                ZooTrace.EVENT_DELIVERY_TRACE_MASK,
   623	                "childWatches.triggerWatch " + parentName);
   624	        }
   625	
   626	        WatcherOrBitSet processed = dataWatches.triggerWatch(path, EventType.NodeDeleted, zxid, acl);
   627	        childWatches.triggerWatch(path, EventType.NodeDeleted, zxid, acl, processed);
   628	        childWatches.triggerWatch("".equals(parentName) ? "/" : parentName,
   629	            EventType.NodeChildrenChanged, zxid, parentAcl);
   630	    }
