   632	    public Stat setData(String path, byte[] data, int version, long zxid, long time) throws NoNodeException {
   633	        Stat s = new Stat();
   634	        DataNode n = nodes.get(path);
   635	        if (n == null) {
   636	            throw new NoNodeException();
   637	        }
   638	        List<ACL> acl;
   639	        byte[] lastData;
   640	        synchronized (n) {
   641	            acl = getACL(n);
   642	            lastData = n.data;
   643	            nodes.preChange(path, n);
   644	            n.data = data;
   645	            n.stat.setMtime(time);
   646	            n.stat.setMzxid(zxid);
   647	            n.stat.setVersion(version);
   648	            n.copyStat(s);
   649	            nodes.postChange(path, n);
   650	        }
   651	
   652	        // first do a quota check if the path is in a quota subtree.
   653	        String lastPrefix = getMaxPrefixWithQuota(path);
   654	        long bytesDiff = (data == null ? 0 : data.length) - (lastData == null ? 0 : lastData.length);
   655	        // now update if the path is in a quota subtree.
   656	        long dataBytes = data == null ? 0 : data.length;
   657	        if (lastPrefix != null) {
   658	            updateQuotaStat(lastPrefix, bytesDiff, 0);
   659	        }
   660	        nodeDataSize.addAndGet(getNodeSize(path, data) - getNodeSize(path, lastData));
   661	
   662	        updateWriteStat(path, dataBytes);
   663	        dataWatches.triggerWatch(path, EventType.NodeDataChanged, zxid, acl);
   664	        return s;
   665	    }
