  1195	    /**
  1196	     * this method gets the count of nodes and the bytes under a subtree
  1197	     *
  1198	     * @param path the path to be used
  1199	     * @param counts the int count
  1200	     */
  1201	    private void getCounts(String path, Counts counts) {
  1202	        DataNode node = getNode(path);
  1203	        if (node == null) {
  1204	            return;
  1205	        }
  1206	        String[] children;
  1207	        int len;
  1208	        synchronized (node) {
  1209	            children = node.getChildren().toArray(new String[0]);
  1210	            len = (node.data == null ? 0 : node.data.length);
  1211	        }
  1212	        // add itself
  1213	        counts.count += 1;
  1214	        counts.bytes += len;
  1215	        for (String child : children) {
  1216	            getCounts(path + "/" + child, counts);
  1217	        }
  1218	    }
