  1490	    public void setWatches(long relativeZxid, List<String> dataWatches, List<String> existWatches, List<String> childWatches,
  1491	                           List<String> persistentWatches, List<String> persistentRecursiveWatches, Watcher watcher) {
  1492	        for (String path : dataWatches) {
  1493	            DataNode node = getNode(path);
  1494	            if (node == null) {
  1495	                watcher.process(new WatchedEvent(EventType.NodeDeleted, KeeperState.SyncConnected, path));
  1496	            } else if (node.stat.getMzxid() > relativeZxid) {
  1497	                watcher.process(new WatchedEvent(EventType.NodeDataChanged, KeeperState.SyncConnected, path));
  1498	            } else {
  1499	                this.dataWatches.addWatch(path, watcher);
  1500	            }
  1501	        }
  1502	        for (String path : existWatches) {
  1503	            DataNode node = getNode(path);
  1504	            if (node != null) {
  1505	                watcher.process(new WatchedEvent(EventType.NodeCreated, KeeperState.SyncConnected, path));
  1506	            } else {
  1507	                this.dataWatches.addWatch(path, watcher);
  1508	            }
  1509	        }
  1510	        for (String path : childWatches) {
  1511	            DataNode node = getNode(path);
  1512	            if (node == null) {
  1513	                watcher.process(new WatchedEvent(EventType.NodeDeleted, KeeperState.SyncConnected, path));
  1514	            } else if (node.stat.getPzxid() > relativeZxid) {
  1515	                watcher.process(new WatchedEvent(EventType.NodeChildrenChanged, KeeperState.SyncConnected, path));
  1516	            } else {
  1517	                this.childWatches.addWatch(path, watcher);
  1518	            }
  1519	        }
  1520	        for (String path : persistentWatches) {
  1521	            this.childWatches.addWatch(path, watcher, WatcherMode.PERSISTENT);
  1522	            this.dataWatches.addWatch(path, watcher, WatcherMode.PERSISTENT);
  1523	        }
  1524	        for (String path : persistentRecursiveWatches) {
  1525	            this.dataWatches.addWatch(path, watcher, WatcherMode.PERSISTENT_RECURSIVE);
  1526	        }
  1527	    }
