  1529	    /**
  1530	     * This method sets the Cversion and Pzxid for the specified node to the
  1531	     * values passed as arguments. The values are modified only if newCversion
  1532	     * is greater than the current Cversion. A NoNodeException is thrown if
  1533	     * a znode for the specified path is not found.
  1534	     *
  1535	     * @param path
  1536	     *     Full path to the znode whose Cversion needs to be modified.
  1537	     *     A "/" at the end of the path is ignored.
  1538	     * @param newCversion
  1539	     *     Value to be assigned to Cversion
  1540	     * @param zxid
  1541	     *     Value to be assigned to Pzxid
  1542	     * @throws NoNodeException
  1543	     *     If znode not found.
  1544	     **/
  1545	    public void setCversionPzxid(String path, int newCversion, long zxid) throws NoNodeException {
  1546	        if (path.endsWith("/")) {
  1547	            path = path.substring(0, path.length() - 1);
  1548	        }
  1549	        DataNode node = nodes.get(path);
  1550	        if (node == null) {
  1551	            throw new NoNodeException(path);
  1552	        }
  1553	        synchronized (node) {
  1554	            if (newCversion == -1) {
  1555	                newCversion = node.stat.getCversion() + 1;
  1556	            }
  1557	            if (newCversion > node.stat.getCversion()) {
  1558	                nodes.preChange(path, node);
  1559	                node.stat.setCversion(newCversion);
  1560	                node.stat.setPzxid(zxid);
  1561	                nodes.postChange(path, node);
  1562	            }
  1563	        }
  1564	    }
