  1646	    /**
  1647	     * Add the digest to the historical list, and update the latest zxid digest.
  1648	     */
  1649	    private void logZxidDigest(long zxid, long digest) {
  1650	        ZxidDigest zxidDigest = new ZxidDigest(zxid, digestCalculator.getDigestVersion(), digest);
  1651	        lastProcessedZxidDigest = zxidDigest;
  1652	        if (zxidDigest.zxid % DIGEST_LOG_INTERVAL == 0) {
  1653	            synchronized (digestLog) {
  1654	                digestLog.add(zxidDigest);
  1655	                if (digestLog.size() > DIGEST_LOG_LIMIT) {
  1656	                    digestLog.poll();
