  1662	    /**
  1663	     * Serializing the digest to snapshot, this is done after the data tree
  1664	     * is being serialized, so when we replay the txns, and it hits this zxid
  1665	     * we know we should be in a non-fuzzy state, and have the same digest.
  1666	     *
  1667	     * @param oa the output stream to write to
  1668	     * @return true if the digest is serialized successfully
  1669	     */
  1670	    public boolean serializeZxidDigest(OutputArchive oa) throws IOException {
  1671	        if (!ZooKeeperServer.isDigestEnabled()) {
  1672	            return false;
  1673	        }
  1674	
  1675	        ZxidDigest zxidDigest = lastProcessedZxidDigest;
  1676	        if (zxidDigest == null) {
  1677	            // write an empty digest
  1678	            zxidDigest = new ZxidDigest();
  1679	        }
  1680	        zxidDigest.serialize(oa);
  1681	        return true;
  1682	    }
  1683	
  1684	    /**
  1685	     * Deserializing the zxid digest from the input stream and update the
  1686	     * digestFromLoadedSnapshot.
  1687	     *
  1688	     * @param ia the input stream to read from
  1689	     * @param startZxidOfSnapshot the zxid of snapshot file
  1690	     * @return the true if it deserialized successfully
  1691	     */
  1692	    public boolean deserializeZxidDigest(InputArchive ia, long startZxidOfSnapshot) throws IOException {
  1693	        if (!ZooKeeperServer.isDigestEnabled()) {
  1694	            return false;
  1695	        }
  1696	
  1697	        try {
  1698	            ZxidDigest zxidDigest = new ZxidDigest();
  1699	            zxidDigest.deserialize(ia);
  1700	            if (zxidDigest.zxid > 0) {
  1701	                digestFromLoadedSnapshot = zxidDigest;
  1702	                LOG.info("The digest in the snapshot has digest version of {}, "
  1703	                        + "with zxid as 0x{}, and digest value as {}",
  1704	                        digestFromLoadedSnapshot.digestVersion,
  1705	                        Long.toHexString(digestFromLoadedSnapshot.zxid),
  1706	                        digestFromLoadedSnapshot.digest);
